result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "ecs.py", "content": """"Minimal ECS: Position, Velocity, static wall AABBs.

Movement integrates velocity into position.
Collision clamps positions out of walls and zeroes the perpendicular velocity.
"""
from dataclasses import dataclass, field


@dataclass
class Position:
    x: float = 0.0
    y: float = 0.0


@dataclass
class Velocity:
    x: float = 0.0
    y: float = 0.0


@dataclass
class Wall:
    """Static axis-aligned bounding box."""
    x: float
    y: float
    w: float
    h: float

    def overlaps(self, pos: Position, radius: float) -> bool:
        return (
            pos.x + radius > self.x
            and pos.x - radius < self.x + self.w
            and pos.y + radius > self.y
            and pos.y - radius < self.y + self.h
        )


@dataclass
class Entity:
    id: int
    position: Position
    velocity: Velocity
    radius: float = 0.5  # treated as an AABB of half-extent `radius` for simplicity


@dataclass
class World:
    entities: list = field(default_factory=list)
    walls: list = field(default_factory=list)


def movement_system(world: World) -> None:
    for e in world.entities:
        e.position.x += e.velocity.x
        e.position.y += e.velocity.y


def collision_system(world: World) -> None:
    for e in world.entities:
        for wall in world.walls:
            if not wall.overlaps(e.position, e.radius):
                continue
            # Push out along the axis of least penetration.
            overlap_left = (e.position.x + e.radius) - wall.x
            overlap_right = (wall.x + wall.w) - (e.position.x - e.radius)
            overlap_top = (e.position.y + e.radius) - wall.y
            overlap_bottom = (wall.y + wall.h) - (e.position.y - e.radius)
            min_overlap = min(overlap_left, overlap_right, overlap_top, overlap_bottom)

            if min_overlap is overlap_left:
                e.position.x -= overlap_left
                e.velocity.x = 0.0
            elif min_overlap is overlap_right:
                e.position.x += overlap_right
                e.velocity.x = 0.0
            elif min_overlap is overlap_top:
                e.position.y -= overlap_top
                e.velocity.y = 0.0
            else:
                e.position.y += overlap_bottom
                e.velocity.y = 0.0


def frame(world: World) -> None:
    # BUG: collision runs before movement. An entity clamped out of a wall
    # this frame immediately moves back into it on this same frame, so the
    # world can end the frame in an overlapping state.
    collision_system(world)
    movement_system(world)


def frame_fixed(world: World) -> None:
    # FIX: move first, then resolve collisions against the post-movement
    # position. The frame always ends with entities outside walls.
    movement_system(world)
    collision_system(world)
